"""Synthetic Game Boy ROM images for the tests: our own generated bytes (a header plus
pseudo-random filler), never real game data. Used by test_pack_library.py and to produce
tests/golden/index_v1.bin."""


def make_rom(title, cart_type, size_code, ram_code, cgb=0, seed=1, size=None, bad_checksum=False):
    """A ROM whose header says `size_code` but whose file is `size` bytes (default: the right size)."""
    expected = (2 << size_code) * 0x4000 if size_code <= 8 else 0x8000
    n = size if size is not None else expected
    state = seed & 0xFFFFFFFF
    rom = bytearray(n)
    for i in range(n):  # small LCG: deterministic filler
        state = (state * 1664525 + 1013904223) & 0xFFFFFFFF
        rom[i] = (state >> 24) & 0xFF
    rom[0x100:0x104] = bytes([0x00, 0xC3, 0x50, 0x01])      # NOP; JP 0x0150
    rom[0x134:0x144] = b"\0" * 16
    rom[0x134:0x134 + len(title)] = title.encode("ascii")
    rom[0x143] = cgb
    rom[0x147] = cart_type
    rom[0x148] = size_code
    rom[0x149] = ram_code
    chk = 0
    for i in range(0x134, 0x14D):
        chk = (chk - rom[i] - 1) & 0xFF
    rom[0x14D] = chk ^ 0xFF if bad_checksum else chk
    return bytes(rom)


# The set behind tests/golden/index_v1.bin. Order matters.
GOLDEN_ROMS = [
    ("tone", make_rom("TONE-ONLY", 0x00, 0, 0, seed=1)),                  # ROM only, 32 KiB
    ("mbc1", make_rom("MBC1 GAME", 0x03, 2, 2, seed=2)),                  # MBC1+RAM+battery, 128 KiB, 8 KiB RAM
    ("mbc3", make_rom("BIG MBC3", 0x13, 5, 3, seed=3)),                   # MBC3+RAM+battery, 1 MiB, 32 KiB RAM
    ("mbc2", make_rom("MBC2 THING", 0x06, 3, 0, seed=4)),                 # MBC2+battery, 256 KiB, 512 B RAM
    ("cgb", make_rom("CGB ONLY", 0x19, 4, 0, cgb=0xC0, seed=5)),          # MBC5, colour only, 512 KiB
    ("cam", make_rom("CAMERA", 0xFC, 0, 0, seed=6)),                      # Pocket Camera: unsupported
    ("short", make_rom("BAD SIZE", 0x00, 1, 0, seed=7, size=40 * 1024)),  # header says 64 KiB, file 40 KiB
]
